import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CegG7-6m.js";var i=JSON.parse(`{"title":"Getting started","description":"","frontmatter":{},"headers":[],"relativePath":"guide/getting-started.md","filePath":"guide/getting-started.md","lastUpdated":1788654326000}`),a={name:`guide/getting-started.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to “Getting started”">​</a></h1><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to “Requirements”">​</a></h2><ul><li>Node.js ≥ 22</li><li>A CalDAV account — Nextcloud, Radicale, Baikal, SOGo, Fastmail, mailbox.org, iCloud, or anything else that speaks the standard</li><li>Its URL, your username, and a password. There is no token to obtain and no scopes to grant; see <a href="/guide/configuration#signing-in">Configuration</a>, and use an app-specific password where the provider offers one</li></ul><h2 id="run-it" tabindex="-1">Run it <a class="header-anchor" href="#run-it" aria-label="Permalink to “Run it”">​</a></h2><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">CALDAV_URL</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">https://dav.example.net</span><span style="--shiki-light:#953800;--shiki-dark:#FFA657;"> \\</span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">CALDAV_USERNAME=you </span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">\\</span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">CALDAV_PASSWORD=your-app-password </span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">\\</span></span>
<span class="line"><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">  npx</span><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;"> -y</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> @ni-c/caldav-mcp</span></span></code></pre></div><p>Nothing is written on startup, and nothing is read either: the server registers its tools and waits. The first tool call is what walks from that URL to the principal and the calendar home set.</p><p>Two more worth setting straight away:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">CALDAV_TIMEZONE</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">Europe/Berlin</span><span style="--shiki-light:#6E7781;--shiki-dark:#8B949E;">   # for a time somebody types without an offset</span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">CALDAV_READ_ONLY</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">true</span><span style="--shiki-light:#6E7781;--shiki-dark:#8B949E;">           # registers the read tools and nothing else</span></span></code></pre></div><p><code>CALDAV_TIMEZONE</code> defaults to UTC, which is rarely what a person means by &quot;three o&#39;clock&quot;. <code>CALDAV_READ_ONLY</code> is worth trying first: it is the cheapest way to see what the server does before letting it change anything.</p><p>Without credentials the server still starts and still lists its tools; every call then fails with setup instructions rather than reaching the network. That is deliberate — a client that probes the tool list at launch should not need a configured account to see one.</p><p>Next: <a href="/guide/clients">connect a client</a>, or read the <a href="/reference/tools">tool reference</a>.</p>`,11)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};